import{_ as a,o as r,c as o,a as s}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"技能只读训练","description":"","frontmatter":{},"headers":[],"relativePath":"training-skill.md","filePath":"training-skill.md","lastUpdated":1787294102000}'),n={name:"training-skill.md"};function e(l,t,d,h,p,i){return r(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="技能只读训练" tabindex="-1">技能只读训练 <a class="header-anchor" href="#技能只读训练" aria-label="Permalink to &quot;技能只读训练&quot;">​</a></h1><blockquote><p><strong>只读训练：答案与解析已展开，无需作答或提交。</strong></p></blockquote><h2 id="检测维修保养方向技能覆盖表" tabindex="-1">检测维修保养方向技能覆盖表 <a class="header-anchor" href="#检测维修保养方向技能覆盖表" aria-label="Permalink to &quot;检测维修保养方向技能覆盖表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>当前题卡</th><th>在本站的作用</th><th>知识页</th></tr></thead><tbody><tr><td>设施监控基础</td><td>S01</td><td>帮助看懂火警、故障、监管、屏蔽/隔离、反馈和控制器状态；不是本方向独立核心职业功能</td><td><a href="/skill/01-monitoring">进入</a></td></tr><tr><td>设施操作</td><td>S02、S19-S22</td><td>先学任务类型、对象/区域确认和完成标准，再学习控制方式、动作、反馈和恢复；检测维修保养方向核心职业功能之一</td><td><a href="/skill/02-operation">进入</a></td></tr><tr><td>设施保养</td><td>S03、S15-S18</td><td>检测维修保养方向核心职业功能之一</td><td><a href="/skill/03-maintenance">进入</a></td></tr><tr><td>设施维修</td><td>S04、S07-S10</td><td>检测维修保养方向核心职业功能之一</td><td><a href="/skill/04-repair">进入</a></td></tr><tr><td>设施检测</td><td>S05、S11-S14</td><td>检测维修保养方向核心职业功能之一</td><td><a href="/skill/05-detection">进入</a></td></tr><tr><td>综合闭环判定</td><td>S06、S23-S25</td><td>把操作、保养、维修、检测放入同一场景中判断</td><td><a href="/skill-roadmap">进入</a></td></tr><tr><td>报警系统设备专项</td><td>S26-S31、S44、S47</td><td>只读练习探测器、手报、控制器、模块、隔离器、主备电和回路通信的检测、故障与恢复</td><td><a href="/skill/alarm-system">进入</a></td></tr><tr><td>水系统设备专项</td><td>S32-S37、S45、S48</td><td>只读练习水源、水箱/水池、泵组、稳压、报警阀、控制阀、末端试水、反馈和恢复的检测维修保养判断</td><td><a href="/skill/water-system">进入</a></td></tr><tr><td>其他消防设施专项</td><td>S38-S43、S46、S49</td><td>只读练习防烟排烟、防火门/卷帘/防火阀、应急照明、消防电话、应急广播、消防电梯、灭火器和消火栓组件的原理差异、检测、故障与恢复</td><td><a href="/skill/other-facilities">进入</a></td></tr></tbody></table><blockquote><p>技能题卡用于阅读任务目标、步骤、反馈、恢复和安全边界；不替代鉴定站现场评分表、设备说明书、单位规程或有资质人员指导。</p></blockquote><p>技能训练采用“场景—答案—步骤—反馈—恢复—安全边界”格式。网页内容用于理解和记忆，不能替代鉴定站现场操作。</p><h2 id="_1-设施监控" tabindex="-1">1. 设施监控 <a class="header-anchor" href="#_1-设施监控" aria-label="Permalink to &quot;1. 设施监控&quot;">​</a></h2><h3 id="题卡-s01-·-场景题-·-l2-·-原创训练题-·-监控操作方向" tabindex="-1">题卡 S01 · 场景题 · L2 · 原创训练题 · 监控操作方向 <a class="header-anchor" href="#题卡-s01-·-场景题-·-l2-·-原创训练题-·-监控操作方向" aria-label="Permalink to &quot;题卡 S01 · 场景题 · L2 · 原创训练题 · 监控操作方向&quot;">​</a></h3><p><strong>场景</strong>：控制器显示某房间火灾报警，但现场暂时没有发现明火。</p><p><strong>标准处置</strong>：记录报警类别、地址和时间 → 按预案通过现场巡查/消防电话等方式核实 → 报告并组织相关处置 → 观察联动和反馈 → 满足条件后复位 → 确认正常监视并记录。</p><p><strong>不能这样做</strong>：直接复位、屏蔽或断电，只为了让声音停止。</p><p><strong>反馈与恢复</strong>：控制器报警信息、现场核实结果、联动动作/反馈、复位后无新增火警或故障。</p><p><strong>安全边界</strong>：不得把“暂未看见明火”当作误报结论；现场核实要遵守单位预案。</p><h2 id="_2-设施操作" tabindex="-1">2. 设施操作 <a class="header-anchor" href="#_2-设施操作" aria-label="Permalink to &quot;2. 设施操作&quot;">​</a></h2><h3 id="题卡-s02-·-程序题-·-l2-·-原创训练题-·-两个方向" tabindex="-1">题卡 S02 · 程序题 · L2 · 原创训练题 · 两个方向 <a class="header-anchor" href="#题卡-s02-·-程序题-·-l2-·-原创训练题-·-两个方向" aria-label="Permalink to &quot;题卡 S02 · 程序题 · L2 · 原创训练题 · 两个方向&quot;">​</a></h3><p><strong>场景</strong>：按训练任务启动消防泵并确认运行结果。</p><p><strong>先学任务拆解</strong>：这道题中的“启动消防泵”只是动作目标，不是完整任务。你还要确认是哪一栋、哪一泵组、服务哪个区域、是查询/测试/控制还是恢复、是否有授权、预期看哪些显示/运行/压力/反馈，以及结束后恢复什么状态。消防泵属于执行对象，控制柜或联动控制器属于控制对象，运行触点/反馈模块属于反馈对象；三者不能混为一个“泵系统”。</p><p><strong>标准步骤</strong>：</p><ol><li>用“位置—对象—动作—目的—预期—恢复”模板复述任务，确认目标泵组、保护区域、操作目的和完成标准；</li><li>核对授权、任务范围、人员安全和是否会影响其他设备；</li><li>确认电源、控制方式、阀门和管网条件；</li><li>按设备说明书选择手动/自动、就地/远程等方式；</li><li>执行启动；</li><li>观察泵组运行、压力、控制柜指示、异常声音/振动和控制器反馈；</li><li>按任务要求停泵或恢复自动状态；</li><li>记录动作结果、反馈、异常和报告对象。</li></ol><p><strong>判定重点</strong>：不是“电机转了”就算完成，还要确认压力和反馈；操作结束不能遗留手动状态或未报告异常。</p><p><strong>安全边界</strong>：实际启停泵必须在鉴定站或有资质人员指导下进行，不能自行关闭阀门、切断电源或制造故障。</p><h3 id="题卡-s19-·-场景题-·-l2-·-原创训练题-·-设施操作" tabindex="-1">题卡 S19 · 场景题 · L2 · 原创训练题 · 设施操作 <a class="header-anchor" href="#题卡-s19-·-场景题-·-l2-·-原创训练题-·-设施操作" aria-label="Permalink to &quot;题卡 S19 · 场景题 · L2 · 原创训练题 · 设施操作&quot;">​</a></h3><p><strong>场景</strong>：控制器显示某区域火警，现场暂未发现明火，操作人员准备立即复位并填写“误报”。</p><p><strong>标准判断</strong>：不能直接复位或下结论。应记录地址、时间和报警类别，按单位预案核实现场，观察联动与反馈并报告；只有满足处置条件后，才按权限复位并确认正常监视。</p><p><strong>易错点</strong>：暂未看见明火不是误报证据；停止报警声也不是完成处置。</p><h3 id="题卡-s20-·-场景题-·-l2-·-原创训练题-·-设施操作" tabindex="-1">题卡 S20 · 场景题 · L2 · 原创训练题 · 设施操作 <a class="header-anchor" href="#题卡-s20-·-场景题-·-l2-·-原创训练题-·-设施操作" aria-label="Permalink to &quot;题卡 S20 · 场景题 · L2 · 原创训练题 · 设施操作&quot;">​</a></h3><p><strong>场景</strong>：按任务启动消防泵，控制柜显示运行，但控制室没有收到运行反馈。</p><p><strong>标准判断</strong>：不能仅凭电机转动判定操作完成。应保留时间和控制方式，核对现场泵组、控制柜、反馈触点/模块、线路和控制器显示，区分“未运行”和“运行无反馈”；按授权复核、报告并恢复规定状态。</p><p><strong>安全边界</strong>：不得为验证而擅自关闭阀门、切断电源或反复启停设备。</p><h3 id="题卡-s21-·-场景题-·-l3-·-原创训练题-·-设施操作" tabindex="-1">题卡 S21 · 场景题 · L3 · 原创训练题 · 设施操作 <a class="header-anchor" href="#题卡-s21-·-场景题-·-l3-·-原创训练题-·-设施操作" aria-label="Permalink to &quot;题卡 S21 · 场景题 · L3 · 原创训练题 · 设施操作&quot;">​</a></h3><p><strong>场景</strong>：测试防烟排烟联动，排烟风机已启动，但风阀位置和反馈状态没有核实。</p><p><strong>标准判断</strong>：联动输出或风机运行不等于系统功能完整。应确认动作区域安全，核对风机运行、风阀实际位置、控制器显示和反馈信号；结束后按方案恢复自动/联动/监视，异常须记录和报告。</p><p><strong>易错点</strong>：只看一个设备的动作，忽略执行机构和反馈链。</p><h3 id="题卡-s22-·-场景题-·-l2-·-原创训练题-·-设施操作" tabindex="-1">题卡 S22 · 场景题 · L2 · 原创训练题 · 设施操作 <a class="header-anchor" href="#题卡-s22-·-场景题-·-l2-·-原创训练题-·-设施操作" aria-label="Permalink to &quot;题卡 S22 · 场景题 · L2 · 原创训练题 · 设施操作&quot;">​</a></h3><p><strong>场景</strong>：应急照明测试结束，灯具已经熄灭，但集中电源仍显示故障，操作人员准备离开。</p><p><strong>标准判断</strong>：不能结束。应记录故障和测试范围，核对集中电源、通信、灯具及控制器状态，按授权转保养/维修/检测；恢复主电和规定常态后再次确认监视状态，并记录未解决问题和报告对象。</p><p><strong>易错点</strong>：灯具亮/灭只是现场现象，不能替代集中电源和故障监视确认。</p><h2 id="_3-设施保养" tabindex="-1">3. 设施保养 <a class="header-anchor" href="#_3-设施保养" aria-label="Permalink to &quot;3. 设施保养&quot;">​</a></h2><h3 id="题卡-s03-·-判断题-·-l1-·-原创训练题" tabindex="-1">题卡 S03 · 判断题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-s03-·-判断题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 S03 · 判断题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防设施保养时，只要外观干净，就可以在记录上填写“功能正常”。</p><p><strong>答案</strong>：错误。</p><p><strong>解析</strong>：外观检查不能替代功能确认。保养应按“外观—连接—状态—功能—记录”检查；功能结果要有相应检查或测试依据，发现故障必须如实记录、报告并按流程处理。</p><p><strong>关联</strong>：<a href="/skill/03-maintenance">设施保养</a>。</p><h2 id="_4-设施维修" tabindex="-1">4. 设施维修 <a class="header-anchor" href="#_4-设施维修" aria-label="Permalink to &quot;4. 设施维修&quot;">​</a></h2><h3 id="题卡-s04-·-场景题-·-l3-·-原创训练题-·-检测维修保养方向" tabindex="-1">题卡 S04 · 场景题 · L3 · 原创训练题 · 检测维修保养方向 <a class="header-anchor" href="#题卡-s04-·-场景题-·-l3-·-原创训练题-·-检测维修保养方向" aria-label="Permalink to &quot;题卡 S04 · 场景题 · L3 · 原创训练题 · 检测维修保养方向&quot;">​</a></h3><p><strong>场景</strong>：控制器提示某探测器故障，维修人员建议直接拔掉探测器让系统恢复“正常”。</p><p><strong>标准处置</strong>：记录地址、时间和现象 → 查看同回路/相关设备是否有共同异常 → 检查安装、污染、接触、线路和环境 → 按授权隔离并落实临时防护 → 使用匹配部件维修或交专业人员处理 → 进行功能验证 → 确认无新增故障 → 恢复自动/联动/监视并记录。</p><p><strong>答案要点</strong>：拔掉设备或屏蔽故障提示不是排除故障，可能扩大消防保护缺口。</p><p><strong>安全边界</strong>：未断电、未验电、未隔离，不拆装电气部件；不得擅自修改地址、联动逻辑和保护参数。</p><h2 id="_5-设施检测" tabindex="-1">5. 设施检测 <a class="header-anchor" href="#_5-设施检测" aria-label="Permalink to &quot;5. 设施检测&quot;">​</a></h2><h3 id="题卡-s05-·-程序题-·-l2-·-原创训练题-·-检测维修保养方向" tabindex="-1">题卡 S05 · 程序题 · L2 · 原创训练题 · 检测维修保养方向 <a class="header-anchor" href="#题卡-s05-·-程序题-·-l2-·-原创训练题-·-检测维修保养方向" aria-label="Permalink to &quot;题卡 S05 · 程序题 · L2 · 原创训练题 · 检测维修保养方向&quot;">​</a></h3><p><strong>场景</strong>：对某报警联动项目进行检测，检测结束后应形成哪些结果记录？</p><p><strong>标准步骤</strong>：检测前核对对象、范围、方案、图纸、仪器和安全隔离 → 通知相关岗位 → 按方案触发输入 → 记录控制器显示 → 观察现场设备动作 → 核对运行/动作/故障反馈 → 按要求复位 → 恢复自动/联动/监视 → 记录异常、判定依据和后续处理。</p><p><strong>五项结果</strong>：输入/触发、控制器显示、现场动作、反馈信号、恢复状态。</p><p><strong>判定重点</strong>：不能只写“设备动作正常”；必须注明方法、仪器、时间、结果、依据文件和异常处理。</p><p><strong>安全边界</strong>：涉及消防泵、风机、卷帘、广播、气体灭火等联动设备时，必须在授权方案和专业人员监护下检测。</p><h3 id="题卡-s07-·-场景题-·-l3-·-原创训练题-·-设施维修" tabindex="-1">题卡 S07 · 场景题 · L3 · 原创训练题 · 设施维修 <a class="header-anchor" href="#题卡-s07-·-场景题-·-l3-·-原创训练题-·-设施维修" aria-label="Permalink to &quot;题卡 S07 · 场景题 · L3 · 原创训练题 · 设施维修&quot;">​</a></h3><p><strong>场景</strong>：同一回路多个设备同时显示通信异常，现场人员建议逐个更换探测器。</p><p><strong>标准判断</strong>：先保留时间、回路和受影响设备范围，核对供电、端子、线路、隔离器和近期施工影响；多个设备共同异常时，应优先考虑回路、供电或通信链路问题，再由授权人员进行分段测试。不能未经判断逐个更换设备，也不能短接线路掩盖故障。</p><p><strong>验证与记录</strong>：维修后确认设备上线、原故障消失、无新增故障，恢复规定监视状态，并记录诊断依据、处理动作、复测结果和报告对象。</p><h3 id="题卡-s08-·-场景题-·-l3-·-原创训练题-·-设施维修" tabindex="-1">题卡 S08 · 场景题 · L3 · 原创训练题 · 设施维修 <a class="header-anchor" href="#题卡-s08-·-场景题-·-l3-·-原创训练题-·-设施维修" aria-label="Permalink to &quot;题卡 S08 · 场景题 · L3 · 原创训练题 · 设施维修&quot;">​</a></h3><p><strong>场景</strong>：控制器提示备用电源故障，现场人员想直接拔掉电池再重新接上。</p><p><strong>标准判断</strong>：先记录故障类别、时间、主备电状态和影响范围；涉及电源部件时必须按授权执行断电、验电、隔离和防误送电，检查开关、保险、接线和蓄电池状态。不能用拔插电池消除提示，也不能在未确认持续监视能力的情况下结束作业。</p><p><strong>验证与记录</strong>：确认主电/备用电源状态、控制器提示、切换结果和规定监视状态，记录异常和复核结果。</p><h3 id="题卡-s09-·-场景题-·-l3-·-原创训练题-·-设施维修" tabindex="-1">题卡 S09 · 场景题 · L3 · 原创训练题 · 设施维修 <a class="header-anchor" href="#题卡-s09-·-场景题-·-l3-·-原创训练题-·-设施维修" aria-label="Permalink to &quot;题卡 S09 · 场景题 · L3 · 原创训练题 · 设施维修&quot;">​</a></h3><p><strong>场景</strong>：联动输出已发出，风机控制柜有显示，但现场没有确认风机运行反馈。</p><p><strong>标准判断</strong>：不能直接填写“联动成功”。应记录输出时间和控制方式，确认现场电源、控制柜、风机、风阀、反馈触点、模块和线路，区分“未输出、未动作、动作无反馈”三类问题，再按授权维修或升级。</p><p><strong>恢复要求</strong>：按方案复测启动、运行/故障反馈和恢复状态，确认运动部件区域安全，记录实际结果和依据文件。</p><h3 id="题卡-s10-·-场景题-·-l3-·-原创训练题-·-设施维修" tabindex="-1">题卡 S10 · 场景题 · L3 · 原创训练题 · 设施维修 <a class="header-anchor" href="#题卡-s10-·-场景题-·-l3-·-原创训练题-·-设施维修" aria-label="Permalink to &quot;题卡 S10 · 场景题 · L3 · 原创训练题 · 设施维修&quot;">​</a></h3><p><strong>场景</strong>：防火卷帘动作到一半停止，现场人员准备站到卷帘下方观察并反复启动。</p><p><strong>标准判断</strong>：立即停止靠近运动部件，保护人员安全并记录停止位置、控制方式、障碍物、限位/反馈和控制器信息；按授权隔离误启动风险，由专业人员检查机械、供电、控制和反馈。</p><p><strong>恢复要求</strong>：维修后按方案验证动作、到位、反馈和恢复，不得用反复启动代替故障判断。</p><h3 id="题卡-s11-·-程序题-·-l2-·-原创训练题-·-设施检测" tabindex="-1">题卡 S11 · 程序题 · L2 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s11-·-程序题-·-l2-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S11 · 程序题 · L2 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：检测报警联动项目，如何选择和记录检测依据？</p><p><strong>标准步骤</strong>：先确认检测对象、系统范围和目的；再查现行标准、检测方案、设计文件、设备说明书和历史记录；核对仪器量程、校准/检定状态和接线；记录触发方法、预期显示/动作/反馈、实际结果、异常和复测。</p><p><strong>判定重点</strong>：不能用网络口诀或单一品牌手册替代适用依据，不能把没有单位和仪器信息的读数直接作为合格结论。</p><h3 id="题卡-s12-·-场景题-·-l3-·-原创训练题-·-设施检测" tabindex="-1">题卡 S12 · 场景题 · L3 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s12-·-场景题-·-l3-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S12 · 场景题 · L3 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：检测中控制器显示输出，现场执行机构没有动作。</p><p><strong>标准判断</strong>：保留原始记录，区分输出已发出但现场未动作与反馈未返回两种情况；分别核对现场电源、执行机构、控制方式、模块、线路和反馈点，按授权落实临时防护并报告。</p><p><strong>复测要求</strong>：维修后重新记录输入/触发、显示、动作、反馈和恢复，不能覆盖原始异常，也不能只记录“已恢复”。</p><h3 id="题卡-s13-·-场景题-·-l3-·-原创训练题-·-设施检测" tabindex="-1">题卡 S13 · 场景题 · L3 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s13-·-场景题-·-l3-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S13 · 场景题 · L3 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：末端试水装置有水流，但控制室没有收到预期信号。</p><p><strong>标准判断</strong>：记录测试点、时间、阀门状态、排水和测量条件；按方案核对水流指示器、压力开关、模块、线路、控制器输入和反馈链。末端有水不能单独证明全系统供水能力或联动功能合格。</p><p><strong>恢复要求</strong>：按方案关闭试水、确认无渗漏，恢复阀门、控制柜自动/联动和控制室监视，记录判定依据和后续维修。</p><h3 id="题卡-s14-·-场景题-·-l2-·-原创训练题-·-设施检测" tabindex="-1">题卡 S14 · 场景题 · L2 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s14-·-场景题-·-l2-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S14 · 场景题 · L2 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：检测结束后，现场设备已经停止，但控制柜仍处于手动状态，控制器还有一条故障信息。</p><p><strong>标准判断</strong>：检测尚未完成。应核实故障和保护影响，按授权恢复自动/联动/监视，不能以设备停止作为完成依据；无法恢复时要报告并落实临时防护。</p><p><strong>记录要求</strong>：写明原始状态、恢复动作、复核结果、未解决问题和报告对象。</p><h3 id="题卡-s15-·-场景题-·-l2-·-原创训练题-·-设施保养" tabindex="-1">题卡 S15 · 场景题 · L2 · 原创训练题 · 设施保养 <a class="header-anchor" href="#题卡-s15-·-场景题-·-l2-·-原创训练题-·-设施保养" aria-label="Permalink to &quot;题卡 S15 · 场景题 · L2 · 原创训练题 · 设施保养&quot;">​</a></h3><p><strong>场景</strong>：报警控制器外观清洁完成，屏幕无明显异常，但历史记录中仍有未处理故障，现场人员准备填写“保养正常”。</p><p><strong>答案</strong>：不能直接填写“正常”。应核对故障对象、影响范围和屏蔽/隔离状态，按制度报告并转维修或检测流程；保养结束要确认规定监视状态、临时措施和记录完整。</p><p><strong>易错点</strong>：清洁、屏幕正常不等于功能和记录状态正常。</p><h3 id="题卡-s16-·-场景题-·-l3-·-原创训练题-·-设施保养" tabindex="-1">题卡 S16 · 场景题 · L3 · 原创训练题 · 设施保养 <a class="header-anchor" href="#题卡-s16-·-场景题-·-l3-·-原创训练题-·-设施保养" aria-label="Permalink to &quot;题卡 S16 · 场景题 · L3 · 原创训练题 · 设施保养&quot;">​</a></h3><p><strong>场景</strong>：水系统保养时发现分区控制阀未处于规定状态，现场人员想直接关闭阀门后拆下信号部件检查。</p><p><strong>答案</strong>：先确认保护影响、停用范围、授权和临时防护，报告责任人员；未经审批不得关闭消防给水阀门或拆卸信号部件。处理后要恢复阀门、供电、自动/联动和控制室监视，并记录复核结果。</p><p><strong>易错点</strong>：把“检查阀门”变成擅自改变消防供水状态。</p><h3 id="题卡-s17-·-场景题-·-l2-·-原创训练题-·-设施保养" tabindex="-1">题卡 S17 · 场景题 · L2 · 原创训练题 · 设施保养 <a class="header-anchor" href="#题卡-s17-·-场景题-·-l2-·-原创训练题-·-设施保养" aria-label="Permalink to &quot;题卡 S17 · 场景题 · L2 · 原创训练题 · 设施保养&quot;">​</a></h3><p><strong>场景</strong>：防火卷帘下方有货物堆放，保养人员准备先启动卷帘确认电机是否正常。</p><p><strong>答案</strong>：应先清理并警戒动作区域，确认无人、无障碍和测试授权，再按方案检查。若发现帘面、导轨或限位异常，应停止反复动作并转维修，不得在卷帘下方站人或用屏蔽代替处理。</p><p><strong>易错点</strong>：保养前置安全不满足时，不能为了完成动作而强行测试。</p><h3 id="题卡-s18-·-场景题-·-l2-·-原创训练题-·-设施保养" tabindex="-1">题卡 S18 · 场景题 · L2 · 原创训练题 · 设施保养 <a class="header-anchor" href="#题卡-s18-·-场景题-·-l2-·-原创训练题-·-设施保养" aria-label="Permalink to &quot;题卡 S18 · 场景题 · L2 · 原创训练题 · 设施保养&quot;">​</a></h3><p><strong>场景</strong>：应急照明保养后，灯具已经点亮，但集中电源仍显示故障，现场人员认为灯亮即可结束。</p><p><strong>答案</strong>：不能结束。应记录故障，核对集中电源、通信、充电和灯具状态，按授权转维修或检测；完成后恢复主电、常态显示并确认无新增故障，记录依据和复核人员。</p><p><strong>易错点</strong>：现场灯具点亮只证明一个现象，不能替代系统状态和故障监视确认。</p><h2 id="_6-综合闭环训练" tabindex="-1">6. 综合闭环训练 <a class="header-anchor" href="#_6-综合闭环训练" aria-label="Permalink to &quot;6. 综合闭环训练&quot;">​</a></h2><h3 id="题卡-s23-·-综合场景题-·-l3-·-原创训练题-·-检测维修保养" tabindex="-1">题卡 S23 · 综合场景题 · L3 · 原创训练题 · 检测维修保养 <a class="header-anchor" href="#题卡-s23-·-综合场景题-·-l3-·-原创训练题-·-检测维修保养" aria-label="Permalink to &quot;题卡 S23 · 综合场景题 · L3 · 原创训练题 · 检测维修保养&quot;">​</a></h3><p><strong>场景</strong>：检测消防联动时，控制器显示输出，风机短暂运行后停止；现场仍有一条故障，控制柜处于手动状态。现场人员准备复位、清除故障后结束检测。</p><p><strong>标准判断</strong>：不能覆盖原始异常，也不能把短暂运行当作联动合格。应保留触发时间、控制方式、显示、风机动作、停止现象、反馈和故障信息，先确认人员和运动部件安全，再区分输出、现场动作、运行保持和反馈链问题；按授权落实隔离或临时防护，转维修复测。</p><p><strong>恢复与记录</strong>：维修或复测后，按方案重新核对输入/触发、控制器显示、现场动作、运行/故障反馈和规定恢复状态；若仍不能恢复自动、联动、监视，应报告责任人员并记录未解决问题。</p><h3 id="题卡-s24-·-综合场景题-·-l3-·-原创训练题-·-检测维修保养" tabindex="-1">题卡 S24 · 综合场景题 · L3 · 原创训练题 · 检测维修保养 <a class="header-anchor" href="#题卡-s24-·-综合场景题-·-l3-·-原创训练题-·-检测维修保养" aria-label="Permalink to &quot;题卡 S24 · 综合场景题 · L3 · 原创训练题 · 检测维修保养&quot;">​</a></h3><p><strong>场景</strong>：水系统保养结束后，控制阀已恢复，但控制室显示监管异常；现场人员认为阀门已经打开即可关闭工单。</p><p><strong>标准判断</strong>：不能结束。应核对阀门实际位置、信号部件、线路、控制器显示和保护影响，确认是状态未恢复、反馈未返回还是设备故障；按授权复核并转维修/检测，不能用屏蔽或删除记录消除异常。</p><p><strong>恢复与记录</strong>：确认规定阀门状态、自动/联动/监视状态、异常处理结果和报告对象，记录保养前后状态及复核证据。</p><h3 id="题卡-s25-·-综合场景题-·-l2-·-原创训练题-·-检测维修保养" tabindex="-1">题卡 S25 · 综合场景题 · L2 · 原创训练题 · 检测维修保养 <a class="header-anchor" href="#题卡-s25-·-综合场景题-·-l2-·-原创训练题-·-检测维修保养" aria-label="Permalink to &quot;题卡 S25 · 综合场景题 · L2 · 原创训练题 · 检测维修保养&quot;">​</a></h3><p><strong>场景</strong>：报警系统保养发现探测器污染，维修更换后控制器显示正常，但没有记录更换部件、复测方法和恢复时间。</p><p><strong>标准判断</strong>：记录不完整。应补记故障现象、处理动作、部件信息、复测方法、输入/显示/动作/反馈结果、恢复时间和复核人员；“屏幕正常”不能替代可追溯的维修与验证记录。</p><h2 id="_6-报警系统设备专项只读训练" tabindex="-1">6. 报警系统设备专项只读训练 <a class="header-anchor" href="#_6-报警系统设备专项只读训练" aria-label="Permalink to &quot;6. 报警系统设备专项只读训练&quot;">​</a></h2><h3 id="题卡-s26-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S26 · 场景题 · L2 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s26-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S26 · 场景题 · L2 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：某探测器在蒸汽环境附近反复报警，现场人员准备直接调低灵敏度。</p><p><strong>标准判断</strong>：不能直接调参。应保留报警地址和时间，核实蒸汽、粉尘、施工、污染和进水等环境因素，查看历史记录及相邻设备状态，再按设计、说明书和授权方案清洁、隔离或更换并复测。</p><p><strong>关联</strong>：<a href="/skill/alarm-system">报警系统项目卡</a>、<a href="/theory/06-fire-facilities">消防设施</a>。</p><h3 id="题卡-s27-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S27 · 场景题 · L2 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s27-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S27 · 场景题 · L2 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：手动报警按钮触发后，现场指示已变化，但控制器没有对应火警显示。</p><p><strong>标准判断</strong>：先记录触发方式、地址和时间，区分操作机构未到位、复位/锁止机构异常、回路通信异常、地址映射问题和控制器输入显示问题；按产品方法和授权方案分段核查，不得反复敲击、短接或拆壳掩盖。</p><p><strong>恢复与记录</strong>：恢复手报和系统规定监视状态，记录现场指示、控制器显示、回路状态、处理动作和复测结果。</p><h3 id="题卡-s28-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S28 · 场景题 · L3 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s28-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S28 · 场景题 · L3 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：控制器显示某回路输出已启动，但受控风机没有动作；现场人员准备连续触发报警确认。</p><p><strong>标准判断</strong>：停止未经授权的重复触发。应确认测试条件、控制方式和设计逻辑，区分“未输出、已输出未动作、动作无反馈”，再核对输出模块、外部电源、控制柜、风机、风阀和线路；涉及真实联动时按方案监护并转专业维修。</p><p><strong>恢复与记录</strong>：按方案恢复自动/联动/监视，记录输出时间、现场动作、反馈、异常、临时防护和报告对象。</p><h3 id="题卡-s29-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S29 · 场景题 · L3 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s29-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S29 · 场景题 · L3 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：同一回路一段设备同时离线，控制器显示通信故障；现场人员建议逐个更换探测器。</p><p><strong>标准判断</strong>：多个相邻设备共同异常时，先考虑回路、供电、端子、短路隔离器、潮湿或近期施工影响，不应逐个盲目换件。应记录影响范围，按授权分段定位，确认隔离器上下游设备状态，并落实保护缺口的临时防护。</p><p><strong>复测要求</strong>：故障解除后确认设备重新上线、原提示消失、无新增故障，记录回路编号、故障段、依据、处理和恢复结果。</p><h3 id="题卡-s30-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S30 · 场景题 · L2 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s30-·-场景题-·-l2-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S30 · 场景题 · L2 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：控制器提示备用电源故障，主电指示正常，现场人员想拔下电池再接回。</p><p><strong>标准判断</strong>：不能用拔插电池消除提示。应记录时间和影响，核对主备电状态、充电/切换单元、开关、保险、接线和蓄电池状态，按授权执行断电、验电、隔离和监护，并评估持续监视能力。</p><p><strong>恢复与记录</strong>：确认主电、备用电源、切换结果和规定监视状态，记录检测方法、维修边界、临时措施和复核人员。</p><h3 id="题卡-s31-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" tabindex="-1">题卡 S31 · 场景题 · L3 · 原创训练题 · 报警系统设备专项 <a class="header-anchor" href="#题卡-s31-·-场景题-·-l3-·-原创训练题-·-报警系统设备专项" aria-label="Permalink to &quot;题卡 S31 · 场景题 · L3 · 原创训练题 · 报警系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：现场风机已经运行，但控制器没有收到运行反馈，记录人员准备填写“联动正常”。</p><p><strong>标准判断</strong>：不能把现场观察当作反馈合格。应保留输出和动作时间，核对反馈触点、输入模块、线路、点位映射、控制柜状态和控制器通信，区分设备未运行与运行无反馈；按授权维修、复测并落实临时防护。</p><p><strong>记录要求</strong>：重新记录输入/触发、控制器显示、现场动作、运行/故障反馈和恢复状态，不能覆盖原始异常。</p><h3 id="报警系统六类设备复述清单" tabindex="-1">报警系统六类设备复述清单 <a class="header-anchor" href="#报警系统六类设备复述清单" aria-label="Permalink to &quot;报警系统六类设备复述清单&quot;">​</a></h3><p>阅读 S26-S31 后，不看页面也应能分别回答以下问题；如果答不出，回到报警系统对应设备学习卡复习：</p><table tabindex="0"><thead><tr><th>设备</th><th>必须能复述的四件事</th><th>对应专项题</th></tr></thead><tbody><tr><td>探测器</td><td>感知什么、如何形成输入、正常证据、误报/无报时先查什么</td><td>S26</td></tr><tr><td>手动报警按钮</td><td>人工触发与自动探测的区别、触发后的显示、复位和记录</td><td>S27</td></tr><tr><td>输出模块</td><td>指令送到哪里、现场动作如何确认、无动作与无反馈如何区分</td><td>S28</td></tr><tr><td>回路通信/隔离器</td><td>单点与成片异常的区别、影响范围、分段定位和恢复</td><td>S29</td></tr><tr><td>主电/备用电源</td><td>主电、备电、切换分别表示什么，为什么不能拔电池验证</td><td>S30</td></tr><tr><td>输入模块/反馈</td><td>现场触点、模块、控制器显示如何对应，为什么不能短接伪造反馈</td><td>S31</td></tr></tbody></table><p><strong>复述模板</strong>：这是【设备】；它负责【输入/控制/反馈/供电通信】；正常时应看到【证据】；异常先记录【对象、时间、范围】并检查【第一层原因】；不能做【越权动作】；结束要恢复【规定状态】并记录【方法、结果、复核人】。</p><h3 id="水系统六类设备复述清单" tabindex="-1">水系统六类设备复述清单 <a class="header-anchor" href="#水系统六类设备复述清单" aria-label="Permalink to &quot;水系统六类设备复述清单&quot;">​</a></h3><p>阅读水系统项目卡后，不看页面也应能回答：</p><table tabindex="0"><thead><tr><th>设备</th><th>必须能复述的四件事</th><th>对应专项题</th></tr></thead><tbody><tr><td>水池/水箱</td><td>储水作用、液位与补水证据、渗漏/低水位先查什么、不能擅自改变什么</td><td>S32、S45</td></tr><tr><td>主泵/备用泵/稳压泵</td><td>三者职责差异、启动后的水力和反馈证据、泵转无压如何分层、恢复什么状态</td><td>S32-S34、S45</td></tr><tr><td>报警阀组/控制阀</td><td>分区控制与阀位监视的区别、试水报警证据、误关的影响、停用恢复边界</td><td>S35-S37、S48</td></tr><tr><td>水流指示器/压力开关</td><td>水流与压力信号的区别、现场动作到控制器显示的链路、有水无信号先查什么</td><td>S35、S48</td></tr><tr><td>末端试水/排水</td><td>测试目的、压力/出水/排水/信号证据、单点结果边界、关闭后如何收口</td><td>S35、S40、S48</td></tr><tr><td>接合器/消火栓/喷头</td><td>各自服务对象、现场完整性证据、遮挡/缺件/碰撞异常、禁止的带压或拆卸动作</td><td>S36、S43</td></tr></tbody></table><p><strong>水系统复述模板</strong>：这是【设备/部件】；它位于【水流链路和分区】；负责【储水/加压/分区控制/水流或压力反馈/测试/出水】；正常证据包括【水力、机械、控制反馈】；异常先记录【对象、时间、影响范围】并检查【第一层原因】；不能【越权停用、放水、拆卸或改设定】；结束要恢复【阀门、供电、自动/联动、排水和监视】并记录【测点、仪器、结果、依据、复核人】。</p><h2 id="_7-水系统设备专项只读训练" tabindex="-1">7. 水系统设备专项只读训练 <a class="header-anchor" href="#_7-水系统设备专项只读训练" aria-label="Permalink to &quot;7. 水系统设备专项只读训练&quot;">​</a></h2><h3 id="题卡-s32-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S32 · 场景题 · L2 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s32-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S32 · 场景题 · L2 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：消防泵电机已经运行，但压力显示没有按预期变化，现场人员准备继续运行并填写“水泵正常”。</p><p><strong>标准判断</strong>：不能仅凭电机运行判定供水正常。应记录时间、控制方式和压力条件，核对水位、吸水/出水阀、泵组异常、仪表和运行反馈，按授权报告并评估是否需要隔离或临时防护。</p><p><strong>恢复与记录</strong>：记录实际测量值、仪器信息、判定依据和后续处理；不得擅自关阀、拆泵或改设定。</p><h3 id="题卡-s33-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S33 · 场景题 · L3 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s33-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S33 · 场景题 · L3 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：计划验证主备泵切换，现场人员建议先拔掉主泵反馈线，观察备用泵是否启动。</p><p><strong>标准判断</strong>：不能用拔线或人为制造故障替代方案测试。应核对授权、预期触发条件、供电、控制方式、主备泵和阀门状态，按批准方案观察启动、运行、压力和控制室反馈。</p><p><strong>恢复与记录</strong>：完成后恢复自动/联动/监视，记录切换对象、触发方法、现场动作、反馈、异常和复核人。</p><h3 id="题卡-s34-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S34 · 场景题 · L2 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s34-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S34 · 场景题 · L2 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：稳压泵近期频繁启停，操作人员准备提高压力设定，让设备少启动一些。</p><p><strong>标准判断</strong>：不能直接改设定。应保留启停时间和压力记录，核对近期试水/放水是否恢复、管网可见渗漏、阀门状态、压力采集和控制柜信息，再由授权人员判断稳压部件、设定或控制回路问题。</p><p><strong>安全边界</strong>：不得断电、封堵泄漏或以屏蔽信号代替故障处理。</p><h3 id="题卡-s35-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S35 · 场景题 · L3 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s35-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S35 · 场景题 · L3 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：末端试水点有水流，现场人员未看到控制室报警，准备按“末端有水”结束检测。</p><p><strong>标准判断</strong>：不能结束。应记录测试点、分区、时间、压力/排水条件和仪器，分别核对水流指示器、压力开关、模块、线路、控制器显示和复位状态；末端有水不能外推全系统功能合格。</p><p><strong>恢复与记录</strong>：关闭试水并确认无渗漏，恢复阀门、控制柜自动/联动和控制室监视，记录异常和报告对象。</p><h3 id="题卡-s36-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S36 · 场景题 · L3 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s36-·-场景题-·-l3-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S36 · 场景题 · L3 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：报警阀试水时现场有排水，但水力警铃不响，人员准备加大放水量确认声音。</p><p><strong>标准判断</strong>：不能盲目扩大放水。应按方案停止或控制试验，核对阀组状态、试水/排水通路、警铃水路、过滤/延迟部件、压力条件和信号反馈，转授权维修人员处理。</p><p><strong>安全边界</strong>：不得擅自拆阀组、改变设定或扩大保护区影响；完成后要恢复并记录。</p><h3 id="题卡-s37-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" tabindex="-1">题卡 S37 · 场景题 · L2 · 原创训练题 · 水系统设备专项 <a class="header-anchor" href="#题卡-s37-·-场景题-·-l2-·-原创训练题-·-水系统设备专项" aria-label="Permalink to &quot;题卡 S37 · 场景题 · L2 · 原创训练题 · 水系统设备专项&quot;">​</a></h3><p><strong>场景</strong>：水系统试验结束，现场设备已经停止，但控制柜仍手动，控制室还有监管或故障显示。</p><p><strong>标准判断</strong>：检测尚未完成。应逐项核对试水阀、控制阀、供电、自动/联动、排水、现场渗漏和控制室监视，记录无法恢复项并报告，不能清除故障或屏蔽信号来关闭工单。</p><p><strong>恢复与记录</strong>：只有现场与控制室双重确认规定状态恢复，且保留输入、显示、动作、反馈、恢复和判定依据记录，才可结束任务。</p><h3 id="其他设施七类设备复述清单" tabindex="-1">其他设施七类设备复述清单 <a class="header-anchor" href="#其他设施七类设备复述清单" aria-label="Permalink to &quot;其他设施七类设备复述清单&quot;">​</a></h3><p>阅读其他设施项目卡后，不看页面也应能回答：</p><table tabindex="0"><thead><tr><th>设备</th><th>必须能复述的四件事</th><th>对应专项题</th></tr></thead><tbody><tr><td>防烟排烟</td><td>送风与排烟解决什么问题、风机/风阀/反馈如何对应、风机转为何仍不够、如何恢复</td><td>S21、S41、S46</td></tr><tr><td>防火门/卷帘/防火阀</td><td>三者分别隔离什么、现场正常证据、动作安全边界、复位与反馈</td><td>S21、S46</td></tr><tr><td>应急照明/疏散指示</td><td>“看得见”和“往哪里走”的区别、主备电转换、单灯结果边界、恢复常态</td><td>S22、S42、S49</td></tr><tr><td>消防电话/应急广播</td><td>双向通话与分区播报区别、组成和证据、单点异常定位、测试后恢复</td><td>S42、S49</td></tr><tr><td>消防电梯</td><td>迫降含义、输入—动作—楼层—门状态—反馈链、维保协同和禁止动作</td><td>S21、S46</td></tr><tr><td>灭火器</td><td>类型适配、六项外观检查、维修/报废边界、人员安全优先</td><td>T34、S43</td></tr><tr><td>室内消火栓</td><td>箱体与组件、供水与反馈区别、放水前置、测试后恢复</td><td>S36、S48</td></tr></tbody></table><p><strong>其他设施复述模板</strong>：这是【设备】；它解决【防烟/分隔/照明/指引/通信/迫降/灭火取水】问题；由【主要部件】组成；命令发出后现场应发生【动作】并返回【反馈】；正常证据还包括【区域、供电、位置、测量或通话/播报结果】；异常先保护【人员/分隔/疏散/供水】并记录；不能【站在运动部件下、拆线屏蔽、短接安全回路或越权改造】；结束要恢复【自动/联动/监视、供电、阀位、常态模式】并记录【对象、方法、结果、依据和复核人】。</p><h2 id="_8-第六批-常见故障诊断与维修闭环场景" tabindex="-1">8. 第六批：常见故障诊断与维修闭环场景 <a class="header-anchor" href="#_8-第六批-常见故障诊断与维修闭环场景" aria-label="Permalink to &quot;8. 第六批：常见故障诊断与维修闭环场景&quot;">​</a></h2><blockquote><p>以下 S44-S49 为原创只读故障场景题，不是官方真题、官方评分表或标准原文；题卡用于阅读判断。具体阈值、动作方法、维修资质和判定依据以适用文件为准。</p></blockquote><h3 id="题卡-s44-·-场景题-·-l3-·-原创训练题-·-报警系统维修" tabindex="-1">题卡 S44 · 场景题 · L3 · 原创训练题 · 报警系统维修 <a class="header-anchor" href="#题卡-s44-·-场景题-·-l3-·-原创训练题-·-报警系统维修" aria-label="Permalink to &quot;题卡 S44 · 场景题 · L3 · 原创训练题 · 报警系统维修&quot;">​</a></h3><p><strong>场景</strong>：同一回路多个相邻设备同时离线，控制器显示通信故障，现场人员建议逐个更换探测器。</p><p><strong>标准判断</strong>：先保留回路、时间和影响范围，核对共同供电、端子、隔离器、线路、潮湿和近期施工影响，再由授权人员分段定位；不得逐个盲目换件、短接或屏蔽。应评估报警保护缺口并落实值守/报告等临时防护。</p><p><strong>恢复与记录</strong>：记录原始故障、故障段、判断依据、处理动作、设备重新上线、无新增故障、自动/联动/监视恢复和复核人员。</p><h3 id="题卡-s45-·-场景题-·-l3-·-原创训练题-·-水系统维修" tabindex="-1">题卡 S45 · 场景题 · L3 · 原创训练题 · 水系统维修 <a class="header-anchor" href="#题卡-s45-·-场景题-·-l3-·-原创训练题-·-水系统维修" aria-label="Permalink to &quot;题卡 S45 · 场景题 · L3 · 原创训练题 · 水系统维修&quot;">​</a></h3><p><strong>场景</strong>：消防泵电机运行，但压力没有按预期变化，现场人员准备继续运行并填写“水泵正常”。</p><p><strong>标准判断</strong>：不能仅凭电机运行判定供水正常。应记录控制方式、测点、时间和原始压力/流量条件，核对水源、水位、吸水/出水阀、泵组、管网渗漏、仪表和反馈；不得擅自关阀、改设定或反复启停。涉及供水能力不确定时应报告并落实保护范围临时防护。</p><p><strong>恢复与记录</strong>：按适用方案记录仪器、单位、原始值与复测值、泵组运行、反馈、阀门/自动状态和遗留风险。</p><h3 id="题卡-s46-·-场景题-·-l3-·-原创训练题-·-其他设施维修" tabindex="-1">题卡 S46 · 场景题 · L3 · 原创训练题 · 其他设施维修 <a class="header-anchor" href="#题卡-s46-·-场景题-·-l3-·-原创训练题-·-其他设施维修" aria-label="Permalink to &quot;题卡 S46 · 场景题 · L3 · 原创训练题 · 其他设施维修&quot;">​</a></h3><p><strong>场景</strong>：排烟风机已启动，但风阀没有到位反馈，现场人员准备站在风阀附近反复启动确认。</p><p><strong>标准判断</strong>：应先清场并防止误启动，区分风机未运行、风阀未动作、动作无反馈三种情况；再按授权核对供电、执行器、阀体/连杆、限位、反馈模块、线路和逻辑配置。不得站在运动部件附近反复启动，也不得短接反馈。</p><p><strong>恢复与记录</strong>：按方案复测命令、风机运行、风阀实际位置、到位/故障反馈、自动/联动/监视和现场安全状态。</p><h3 id="题卡-s47-·-场景题-·-l3-·-原创训练题-·-报警系统维修" tabindex="-1">题卡 S47 · 场景题 · L3 · 原创训练题 · 报警系统维修 <a class="header-anchor" href="#题卡-s47-·-场景题-·-l3-·-原创训练题-·-报警系统维修" aria-label="Permalink to &quot;题卡 S47 · 场景题 · L3 · 原创训练题 · 报警系统维修&quot;">​</a></h3><p><strong>场景</strong>：备用电源故障持续存在，主电指示正常，现场人员想拔下电池再接回以消除提示。</p><p><strong>标准判断</strong>：不能拔插电池掩盖故障。应记录主备电状态、时间和影响范围，评估持续监视能力，按授权执行断电、验电、隔离和防误送电，核对充电单元、开关、保险、接线和蓄电池状态；超出授权时升级。</p><p><strong>恢复与记录</strong>：记录部件信息、检测/维修依据、切换结果、控制器显示、无新增故障、临时防护撤销时间和复核人。</p><h3 id="题卡-s48-·-场景题-·-l3-·-原创训练题-·-水系统维修" tabindex="-1">题卡 S48 · 场景题 · L3 · 原创训练题 · 水系统维修 <a class="header-anchor" href="#题卡-s48-·-场景题-·-l3-·-原创训练题-·-水系统维修" aria-label="Permalink to &quot;题卡 S48 · 场景题 · L3 · 原创训练题 · 水系统维修&quot;">​</a></h3><p><strong>场景</strong>：末端试水有水流，但控制室没有收到预期信号，现场人员准备按“有水”结束任务。</p><p><strong>标准判断</strong>：不能结束。应保留测试点、分区、阀门、排水和测量条件，区分水流指示器/压力开关动作、模块输入、线路通信和控制器显示问题；不得短接输入，也不能把单点有水外推为全系统合格。若关闭试水或排水条件不安全，应先落实防淹和报告。</p><p><strong>恢复与记录</strong>：关闭试水并确认无渗漏，恢复阀门、控制柜自动/联动/监视，记录输入、显示、反馈、判定依据、异常处理和复核人员。</p><h3 id="题卡-s49-·-场景题-·-l3-·-原创训练题-·-其他设施维修" tabindex="-1">题卡 S49 · 场景题 · L3 · 原创训练题 · 其他设施维修 <a class="header-anchor" href="#题卡-s49-·-场景题-·-l3-·-原创训练题-·-其他设施维修" aria-label="Permalink to &quot;题卡 S49 · 场景题 · L3 · 原创训练题 · 其他设施维修&quot;">​</a></h3><p><strong>场景</strong>：应急照明灯具能够点亮，但集中电源仍显示故障，现场人员准备只写“灯亮正常”并关闭工单。</p><p><strong>标准判断</strong>：不能结束。应记录故障及范围，核对主备电、集中电源、充电、通信、灯具和控制器状态，区分现场点亮与系统故障监视是否一致；按授权转维修/检测，不能删除记录或用屏蔽代替处理。</p><p><strong>恢复与记录</strong>：确认主电、应急转换、集中电源显示、通信、灯具和规定监视状态恢复；记录原始与复测结果、临时措施、遗留风险和报告对象。</p><h2 id="_9-第五批-检测仪器与规范步骤场景" tabindex="-1">9. 第五批：检测仪器与规范步骤场景 <a class="header-anchor" href="#_9-第五批-检测仪器与规范步骤场景" aria-label="Permalink to &quot;9. 第五批：检测仪器与规范步骤场景&quot;">​</a></h2><blockquote><p>以下 S38-S43 均为原创只读检测场景题，不是官方真题、官方评分表或历年题；题卡只用于阅读判断，具体方法、数值和评分以适用依据为准。</p></blockquote><h3 id="题卡-s38-·-场景题-·-l2-·-原创训练题-·-设施检测" tabindex="-1">题卡 S38 · 场景题 · L2 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s38-·-场景题-·-l2-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S38 · 场景题 · L2 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：检测报警回路时，人员把万用表拨到电流档，准备并联到控制器端子，并认为蜂鸣器响就能证明回路功能正常。</p><p><strong>标准判断</strong>：不能这样操作。应先明确测量对象、带电状态、回路类别和方案允许的测量方法，检查表笔插孔、量程、保险、绝缘和校准状态；按说明书/方案接线并记录原始读数。通断现象不能替代输入、显示、动作、反馈和恢复验证。</p><p><strong>异常复测</strong>：若读数异常，保留首次档位、测点和读数，先核对接线与量程，再由授权人员按同一依据复测；不得以换档重测覆盖原记录。</p><h3 id="题卡-s39-·-场景题-·-l3-·-原创训练题-·-设施检测" tabindex="-1">题卡 S39 · 场景题 · L3 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s39-·-场景题-·-l3-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S39 · 场景题 · L3 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：检测某电气回路绝缘时，现场人员未断电、未验电就开始测试，测试结束后也没有放电确认。</p><p><strong>标准判断</strong>：应立即停止。绝缘测试必须先核对适用依据、测试对象和隔离范围，按规程断电、验电、隔离并确认不会影响其他保护功能；测试后按仪器说明书放电，复核恢复状态。绝缘读数不能单独证明整套消防设施功能合格。</p><p><strong>记录重点</strong>：记录隔离对象、测试方法/档位、读数和单位、放电结果、恢复时间及授权/复核人员；异常复测必须保留首次结果。</p><h3 id="题卡-s40-·-场景题-·-l2-·-原创训练题-·-设施检测" tabindex="-1">题卡 S40 · 场景题 · L2 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s40-·-场景题-·-l2-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S40 · 场景题 · L2 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：末端试水检测中，人员用未经核对的压力表读到一个数值，直接与记忆中的固定阈值比较，并据此宣布整个水系统合格。</p><p><strong>标准判断</strong>：不能这样判定。应确认系统形式、测试点、取压条件、仪器量程/接口/校准状态和适用判定依据，记录压力、单位、时间、阀门和排水条件；末端有水或单点压力结果不能外推全系统供水能力。</p><p><strong>异常复测</strong>：若读数与预期不符，先保留原始读数，检查测点、接口、泄漏、阀门和仪器状态，再按方案复测，并分别记录原测与复测。</p><h3 id="题卡-s41-·-场景题-·-l3-·-原创训练题-·-设施检测" tabindex="-1">题卡 S41 · 场景题 · L3 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s41-·-场景题-·-l3-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S41 · 场景题 · L3 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：防烟排烟检测时，人员把风速仪探头固定在一个位置，未记录截面、探头方向和风阀状态，就用单点读数代表整套系统风量。</p><p><strong>标准判断</strong>：证据不足。应按方案确认风机、风阀、测量截面、布点方法、探头方向和环境条件，按规定方法记录各测点原始值及计算过程；风速与风量不能混用，单点结果不能自动代表整截面或系统性能。</p><p><strong>恢复与复测</strong>：保留首次测量条件和读数，调整到方案规定的测点/方法后复测，记录风机风阀状态、各点数据、单位、计算方法和判定依据。</p><h3 id="题卡-s42-·-场景题-·-l2-·-原创训练题-·-设施检测" tabindex="-1">题卡 S42 · 场景题 · L2 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s42-·-场景题-·-l2-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S42 · 场景题 · L2 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：测试应急广播时，人员在扬声器旁测得声音很大，未记录背景噪声、分区和声级计设置，便填写“全楼广播合格”。</p><p><strong>标准判断</strong>：不能结束。应按方案确认分区、测点、背景条件、计权/响应设置和校准状态，分别记录设备模式、背景和原始读数；单点近距离读数不能替代指定区域和分区效果判断。</p><p><strong>异常复测</strong>：背景突变、设置错误或读数不稳定时，保留首次记录并说明原因，恢复适用设置后按方案复测；不得挑选有利读数覆盖异常。</p><h3 id="题卡-s43-·-场景题-·-l3-·-原创训练题-·-设施检测" tabindex="-1">题卡 S43 · 场景题 · L3 · 原创训练题 · 设施检测 <a class="header-anchor" href="#题卡-s43-·-场景题-·-l3-·-原创训练题-·-设施检测" aria-label="Permalink to &quot;题卡 S43 · 场景题 · L3 · 原创训练题 · 设施检测&quot;">​</a></h3><p><strong>场景</strong>：烟感模拟工具触发探测器后，控制器显示报警，但现场人员没有记录工具型号、探测器类型、联动反馈和复位状态，准备只写“测试正常”。</p><p><strong>标准判断</strong>：记录不完整，不能直接下结论。应确认工具与探测器类型匹配、工具状态和授权条件，记录地址/区域、模拟方式、控制器显示、声光/联动动作、运行/到位/故障反馈和恢复结果；不得用真实烟火或不适配介质替代。</p><p><strong>异常复测</strong>：若显示、动作或反馈不一致，保留首次结果，区分输入、显示、输出、现场动作和反馈环节，按方案维修或复测；复测记录必须与原始异常并列保存。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先确认对象和安全</span></span>
<span class="line"><span>再选择控制方式</span></span>
<span class="line"><span>按规程执行动作</span></span>
<span class="line"><span>同时观察现场和反馈</span></span>
<span class="line"><span>恢复规定状态</span></span>
<span class="line"><span>记录并报告结果</span></span></code></pre></div><blockquote><p>以上技能卡均为依据职业标准和安全原则编写的原创训练题/场景，不是官方评分表或历年真题。实际设备操作、评分点和关键技能判定以鉴定站现场要求为准。</p></blockquote><h2 id="_6-只读技能判定清单" tabindex="-1">6. 只读技能判定清单 <a class="header-anchor" href="#_6-只读技能判定清单" aria-label="Permalink to &quot;6. 只读技能判定清单&quot;">​</a></h2><p>阅读技能题时，不要只背“按哪个按钮”。每道题都应能从以下六个问题看出是否完成闭环：</p><table tabindex="0"><thead><tr><th>检查问题</th><th>需要看到的证据</th></tr></thead><tbody><tr><td>任务是否明确</td><td>对象、区域、目标、授权和影响范围已经确认</td></tr><tr><td>安全是否确认</td><td>人员、设备、供电、阀门、联动影响和监护条件已核对</td></tr><tr><td>操作是否规范</td><td>控制方式、执行顺序和设备说明书要求一致</td></tr><tr><td>反馈是否核实</td><td>控制器显示、现场动作、运行状态、故障或反馈信号有记录</td></tr><tr><td>状态是否恢复</td><td>按任务要求恢复自动、联动、监视或规定的临时防护状态</td></tr><tr><td>结果是否可追溯</td><td>时间、对象、方法、结果、异常和报告对象已经记录</td></tr></tbody></table><h3 id="题卡-s06-·-场景题-·-l3-·-原创训练题-·-两个方向" tabindex="-1">题卡 S06 · 场景题 · L3 · 原创训练题 · 两个方向 <a class="header-anchor" href="#题卡-s06-·-场景题-·-l3-·-原创训练题-·-两个方向" aria-label="Permalink to &quot;题卡 S06 · 场景题 · L3 · 原创训练题 · 两个方向&quot;">​</a></h3><p><strong>场景</strong>：训练结束后，现场设备已经停止，但控制柜仍处于手动状态，控制器显示一条未处理的故障信息。</p><p><strong>标准判断</strong>：不能直接宣布“操作完成”。应确认设备是否按任务要求恢复自动/联动状态，核实故障信息和保护影响，按权限采取临时防护措施，报告责任人员，并将异常和恢复结果写入记录。</p><p><strong>易错点</strong>：把“设备停止”误当成“系统恢复”；把“没有听到报警声”误当成“没有故障”。</p><p><strong>关联</strong>：<a href="/skill/02-operation">设施操作</a>、<a href="/skill/01-monitoring">设施监控</a>、<a href="/training-labels">题源与标记说明</a>。</p><h2 id="_7-你的方向-检测维修保养" tabindex="-1">7. 你的方向：检测维修保养 <a class="header-anchor" href="#_7-你的方向-检测维修保养" aria-label="Permalink to &quot;7. 你的方向：检测维修保养&quot;">​</a></h2><p>你应把本页内容按以下优先级掌握：</p><ol><li><strong>设施操作</strong>：会确认控制方式，执行动作，观察现场和反馈，并恢复状态；</li><li><strong>设施保养</strong>：会按外观、连接、状态、功能、记录组织检查；</li><li><strong>设施维修</strong>：会按现象、判断、安全隔离、处理、验证、记录描述故障闭环；</li><li><strong>设施检测</strong>：会按方案记录输入、显示、动作、反馈、恢复和判定。</li></ol><p>设施监控仍是基础，因为你必须先看懂报警、故障、监管、屏蔽/隔离和联动反馈，才能判断维修或检测结果。</p><table tabindex="0"><thead><tr><th>方向</th><th>重点关注</th><th>不应混淆</th></tr></thead><tbody><tr><td>消防设施监控操作</td><td>监视、识别、记录、报告、控制方式和状态恢复</td><td>不能把监控判断当成擅自维修</td></tr><tr><td>消防设施检测维修保养</td><td>检测方案、维修隔离、功能验证、结果判定和记录</td><td>不能把一次观察当成完整检测</td></tr></tbody></table><p>两类方向可能共享设备和信号链，但考核任务、授权范围、评分项目和现场设备配置可能不同。页面中的场景题用于建立判断框架，不能替代当批次评分表。</p>`,246)])])}const c=a(n,[["render",e]]);export{b as __pageData,c as default};
